WITH scored AS (SELECT id, store_id, product_id, sale_date, units, revenue, SUM(revenue) OVER w_recent AS running_sum_revenue, MIN(revenue) OVER w_recent AS running_min_revenue, MAX(revenue) OVER w_recent AS running_max_revenue, AVG(revenue) OVER w_recent AS running_avg_revenue FROM store_sales WINDOW w_recent AS (PARTITION BY product_id ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT s.id, s.product_id, s.sale_date, s.units, s.revenue, s.running_sum_revenue, s.running_avg_revenue, (SELECT SUM(t2.units) FROM store_sales t2 WHERE t2.product_id = s.product_id) AS sum_store_sale_units FROM scored s ORDER BY sum_store_sale_units DESC
